effect.shader:
// k ÷ 255 com o arredondamento certo: o float EXATO que a textura de 8 bits devolve ao AM (ver `am-color-balance.xml`).
float oitoBits(float k) {
    uint n = uint(k);
    if (n == 0u) return 0.0;
    if (n == 255u) return 1.0;
    int j = 0;                                                    // o bit mais alto de n
    for (int i = 1; i < 8; i++) if (n >= (1u << uint(i))) j = i;
    int e = 31 - j;
    uint q = ((n << uint(e)) + 127u) / 255u;                      // entre 2^23 e 2^24
    return uintBitsToFloat((uint(150 - e) << 23) + (q - 0x800000u));
}

void main() {
    vec4 camada = texture(inputImg, acScreenNorm);
    float alfa = camada.a;
    // A camada do AM chega pré-multiplicada EM 8 BITS: arredondada aqui do mesmo jeito (o premul do Android). No
    // opaco a cor já é o float da textura, bit a bit. A cor lida passa pelo mediump, como o `texColor` do AM.
    mediump vec3 cor = camada.rgb;
    if (alfa < 1.0) {
        vec3 k = floor(camada.rgb * alfa * 255.0 + 0.5);
        cor = vec3(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b));
    }

    // A conta do AM, na mesma forma (vetor × matriz, as matrizes dele) e nas mesmas precisões.
    highp mat3 rgbParaYuv = mat3(
         0.299,     0.587,    0.114,
        -0.14713,  -0.28886,  0.436,
         0.615,    -0.51499, -0.10001
    );
    highp mat3 yuvParaRgb = mat3(
        1.0,  0.0,      1.13983,
        1.0, -0.39465, -0.58060,
        1.0,  2.03211,  0.0
    );
    mediump float vibracao = vib;
    mediump float saturacao = saturation;
    highp vec3 rgb = cor;
    highp vec3 yuv = rgb * rgbParaYuv;

    // A Vibração: o croma aumentado, misturado de volta pela saturação que a cor já tinha.
    mediump float saturacaoDePartida = min(1.0, length(yuv.yz) * 2.5);
    mediump vec2 cromaAumentado = yuv.yz * vibracao;
    yuv.yz = mix(cromaAumentado, yuv.yz, saturacaoDePartida);

    // A Saturação, depois.
    yuv.yz = yuv.yz * (saturacao + 1.0);
    rgb = yuv * yuvParaRgb;

    vec3 saida = clamp(rgb, 0.0, 1.0);                           // o buffer de 8 bits do AM corta em 0 e 1
    fragColor = alfa > 0.0 ? vec4(min(saida / alfa, vec3(1.0)), alfa) : vec4(0.0);
}
